// Placeholder models generated by code. Origin: bottom center (see mesher).
import { VoxelObject } from './voxel-object.js';
import { P, PALETTE } from './palette.js';
import { CFG, LAYOUT } from './config/index.js';

// The models are described in cm (the old 1 cm grid: a "voxel" below is 1 cm, sizes are in these) and sampled on the
// voxel grid of the game, so they keep their size and gain detail when the voxel gets smaller. `at(u, v, w)` gives
// the palette index (0 = empty) at a point in those cm coordinates: the old voxel i spans i - 0.5 .. i + 0.5.
const UNIT = 0.01;
const K = UNIT / LAYOUT.voxel;

function sample(size, at) {
  const grid = size.map((n) => Math.max(1, Math.round(n * K)));
  const o = VoxelObject.empty(...grid, PALETTE);
  const cm = (i, axis) => ((i + 0.5) * size[axis]) / grid[axis] - 0.5; // the center of cell i in cm coordinates
  for (let z = 0; z < grid[2]; z++) {
    for (let y = 0; y < grid[1]; y++) {
      for (let x = 0; x < grid[0]; x++) o.set(x, y, z, at(cm(x, 0), cm(y, 1), cm(z, 2)));
    }
  }
  return o;
}

const CRUCIBLE_RADIUS = [2.5, 3.2, 3.8, 4.2, 4.4, 4.5, 4.5];
// the bowl's radius at height v (cm), between the layers
const crucibleRadius = (v) => {
  const t = Math.min(6, Math.max(0, v));
  const i = Math.min(5, Math.floor(t));
  return CRUCIBLE_RADIUS[i] + (CRUCIBLE_RADIUS[i + 1] - CRUCIBLE_RADIUS[i]) * (t - i);
};

export function leadColor(temp) {
  if (temp >= CFG.CRITICAL) return P.LEAD_CRIT;
  if (temp >= CFG.MELT) return P.LEAD_HOT;
  if (temp >= CFG.MELT / 2) return P.LEAD_WARM;
  return P.LEAD_COLD;
}

// Stack of colored layers inside the crucible, bottom to top.
export function crucibleContents(c) {
  switch (c.content) {
    case 'lead': {
      const stack = [{ color: leadColor(c.temp), layers: 2 }];
      const mercury = Math.round((c.amounts.hg ?? 0) * 2);
      if (mercury > 0) stack.push({ color: P.MERCURY, layers: mercury });
      return stack;
    }
    case 'amalgam': {
      const stack = [{ color: c.quality >= 0.6 ? P.AMALGAM_GOOD : P.AMALGAM_POOR, layers: 3 }];
      const sulfur = c.amounts.sulfur ?? 0;
      if (sulfur > 0) stack.push({ color: P.SULFUR, layers: Math.min(2, Math.ceil(sulfur * 3)) });
      return stack;
    }
    case 'gold': return [{ color: P.GOLD, layers: 3 }];
    case 'dull': return [{ color: P.GOLD_DULL, layers: 3 }];
    case 'fools': return [{ color: P.FOOLS, layers: 3 }];
    case 'slag': return [{ color: P.SLAG, layers: 3 }];
    case 'sludge': return [{ color: P.SLUDGE, layers: 3 }];
    case 'burnt': return [{ color: P.BURNT, layers: 1 }];
    default: return [];
  }
}

// 9x7x9 cm bowl, 1.2 cm wall; interior layers y = 1..5 (the contents stack in them).
export function crucibleModel(contents) {
  const layers = contents.flatMap(({ color, layers: n }) => Array(n).fill(color)).slice(0, 5);
  return sample([9, 7, 9], (u, v, w) => {
    const d = Math.hypot(u - 4, w - 4);
    const radius = crucibleRadius(v);
    if (d > radius) return 0;
    if (v < 0.5 || d > radius - 1.2) return P.CRUCIBLE;
    return layers[Math.round(v) - 1] ?? 0;
  });
}

export const FLAME_FRAMES = 4;
const FLAME_HEIGHT = [1, 2, 3, 2]; // cm above the wick

// 9x7x9 cm tripod with a tea light inside and a ring on top (crucible sits on it); flame -1 = unlit.
export function standModel(flame) {
  return sample([9, 7, 9], (u, v, w) => {
    const d = Math.hypot(u - 4, w - 4);
    let color = 0;
    if (v < 0.5 && d <= 4.2) color = P.BRONZE;
    if (v >= 5.5 && d > 1.6 && d <= 3.3) color = P.BRONZE;
    if (v >= 0.5 && v < 2.5 && d <= 2.2) color = P.WAX;
    for (const [px, pz] of [[2, 2], [6, 2], [2, 6], [6, 6]]) {
      if (v >= 0.5 && v < 5.5 && Math.abs(u - px) < 0.5 && Math.abs(w - pz) < 0.5) color = P.BRONZE;
    }
    if (Math.abs(u - 4) < 0.5 && Math.abs(v - 3) < 0.5 && Math.abs(w - 4) < 0.5) color = P.BURNT; // wick
    const h = Math.round(v) - 3;
    if (flame >= 0 && h >= 1 && h <= FLAME_HEIGHT[flame] && d <= (h === 1 ? 1.2 : 0.5)) color = h === 1 ? P.FLAME_A : P.FLAME_B;
    return color;
  });
}

// 1x7x1 cm match: wood 0..3.5, head 3.5..4.5 (gone when broken off), flame 4.5..6.5 when lit.
export function matchModel(lit, broken = false) {
  return sample([1, 7, 1], (u, v) => {
    if (v < 3.5) return P.MATCH_WOOD;
    if (v < 4.5) return broken ? 0 : P.MATCH_HEAD;
    if (!lit) return 0;
    return v < 5.5 ? P.FLAME_A : P.FLAME_B;
  });
}

// 6x3x4 cm matchbox with a striker strip on top; one red match head per match left.
export function matchboxModel(left) {
  return sample([6, 3, 4], (u, v, w) => {
    const top = Math.round(v) === 2;
    for (let i = 0; i < left; i++) {
      if (top && u >= 0.5 + i && u < 1.5 + i && w >= 2.5 && w < 3.5) return P.MATCH_HEAD;
    }
    return top && u >= 0.5 && u < 4.5 && w >= 0.5 && w < 2.5 ? P.STRIKER : P.BOX;
  });
}

// 7x3x7 cm dish with a heap of powder (sulfur unless said otherwise).
export function dishModel(powder = P.SULFUR) {
  return sample([7, 3, 7], (u, v, w) => {
    const d = Math.hypot(u - 3, w - 3);
    const layer = Math.round(v);
    if (layer === 0) return d <= 3.4 ? P.DISH : 0;
    if (layer === 1) return d <= 2.2 ? powder : d <= 3.4 ? P.DISH : 0;
    return d <= 1.2 ? powder : 0;
  });
}

// 1.5x15x1.5 cm stirring rod (thin enough to pinch), the bottom end is the tip.
export function rodModel() {
  return sample([1.5, 15, 1.5], () => P.ROD);
}

// 3x2x2 cm gold nugget; the kind decides the color (real gold, dull gold or fool's gold).
export function nuggetModel(kind) {
  const color = kind === 'gold' ? P.GOLD : kind === 'dull' ? P.GOLD_DULL : P.FOOLS;
  return sample([3, 2, 2], () => color);
}

// 10x16x8 cm sheet ghost: a dome head, a wavy hem (two frames), dark eyes on the front (+z).
export function ghostModel(frame = 0) {
  return sample([10, 16, 8], (u, v, w) => {
    const cx = 4.5;
    const cz = 3.5;
    const hem = 2.5 + (Math.round(Math.atan2(w - cz, u - cx) * 2 + frame * 2) % 2 === 0 ? 0 : 1.2); // a wavy lower edge
    if (v < hem) return 0;
    const head = v > 9 ? Math.sqrt(Math.max(0, 1 - ((v - 9) / 7) ** 2)) : 1;
    const inside = ((u - cx) / (4.8 * head)) ** 2 + ((w - cz) / (3.6 * head)) ** 2 <= 1;
    if (!inside) return 0;
    const eye = w >= 5.6 && v >= 10 && v <= 12 && Math.abs(Math.abs(u - cx) - 1.8) <= 0.9;
    return eye ? P.BURNT : P.GHOST;
  });
}

// 17x10x6 cm cat facing +x: straw (a figure) or alive (black, legs in two frames when it runs). `eyes` = the gold kind
// lying in its eye sockets, or null for dark ones.
export function catModel(look, eyes = null, frame = 0) {
  const color = look === 'alive' ? P.CAT : P.GOLD_DULL;
  const eyeColor = eyes === 'gold' ? P.GOLD : eyes === 'dull' ? P.GOLD_DULL : eyes === 'fools' ? P.FOOLS : P.BURNT;
  return sample([17, 10, 6], (u, v, w) => {
    const body = ((u - 7) / 5.5) ** 2 + ((v - 4.5) / 2.6) ** 2 + ((w - 2.5) / 2.2) ** 2 <= 1;
    const head = ((u - 13.5) / 2.6) ** 2 + ((v - 6.2) / 2.6) ** 2 + ((w - 2.5) / 2.4) ** 2 <= 1;
    const ears = v >= 8 && v <= 9.6 && (Math.abs(w - 1) <= 0.7 || Math.abs(w - 4) <= 0.7) && Math.abs(u - 13.2) <= 1;
    const tail = u <= 2.5 && v >= 4 + (2.5 - u) * 1.2 && v <= 5.6 + (2.5 - u) * 1.2 && Math.abs(w - 2.5) <= 0.8;
    const stride = look === 'alive' && frame === 1 ? 1 : 0;
    const legs = v <= 2.2 && (Math.abs(u - (4 + stride)) <= 0.9 || Math.abs(u - (10 - stride)) <= 0.9) && (Math.abs(w - 1) <= 0.8 || Math.abs(w - 4) <= 0.8);
    const eye = u >= 15 && v >= 6.4 && v <= 7.8 && (Math.abs(w - 1.2) <= 0.7 || Math.abs(w - 3.8) <= 0.7);
    if (eye && head) return eyeColor;
    return body || head || ears || tail || legs ? color : 0;
  });
}

// 10x4x10 cm cushion
export function cushionModel() {
  return sample([10, 4, 10], (u, v, w) => (Math.abs(u - 4.5) <= 4.5 && Math.abs(w - 4.5) <= 4.5 && v <= 3.2 - 0.6 * (Math.max(Math.abs(u - 4.5), Math.abs(w - 4.5)) > 3.5 ? 1 : 0) ? P.BOX : 0));
}
